/**
 * Messages, cut 6 (email in): a file that reads as a paper a trade partner's step waits on. Only a trade partner's
 * W-9 and certificate of insurance for now (the lead's answer to Q7), read from the file's name and kind. The thread
 * offers *File this as their certificate*; the app never files a paper by itself (decision 5's lean,
 * `email-in-mockups.html` screen 3).
 */

export type PaperGuess = 'coi' | 'w9'

/** The words the offer says each paper is. */
export const PAPER_GUESS_WORDS: Readonly<Record<PaperGuess, { paper: string; press: string }>> = {
  coi: { paper: 'certificate of insurance', press: 'File this as their certificate' },
  w9: { paper: 'W-9', press: 'File this as their W-9' },
}

const COI = /(?:^|[^a-z0-9])(?:coi|acord(?:[\s_-]*25)?|cert(?:ificate)?[\s_.-]*(?:of[\s_.-]*)?(?:liability[\s_.-]*)?ins(?:urance)?|insurance[\s_.-]*cert(?:ificate)?)(?![a-z])/i
const W9 = /(?:^|[^a-z0-9])w[\s_.-]?9(?![0-9])/i

/** A PDF, or a picture (a scan or a phone's photo of the paper). */
const readable = (mime: string, name: string): boolean => /^(?:application\/pdf|image\/)/i.test(mime) || /\.(?:pdf|jpe?g|png|heic|tiff?)$/i.test(name)

/** The paper a file reads as, for a trade partner's email, or null. A name that reads as both reads as neither. */
export function paperGuess(file: { name: string; mime: string }, senderKind: string | null): PaperGuess | null {
  if (senderKind !== 'trade' || !readable(file.mime, file.name)) return null
  const name = file.name.replace(/\.[a-z0-9]{2,5}$/i, '')
  const coi = COI.test(name)
  const w9 = W9.test(name)
  return coi === w9 ? null : coi ? 'coi' : 'w9'
}
